 commands="git status\ngit worktree add ../11-hotfix -b hotfix main\ngit worktree list\n# Inspect the hotfix directory; the original dirty file remains unchanged.\ngit -C ../11-hotfix status\ngit worktree remove ../11-hotfix\ngit status",
 steps=["I observe the dirty change in the original directory.","I create an independent clean checkout and inspect both contexts.","I remove the clean worktree and verify the original edit remains."],
 why="Worktrees share objects and refs while keeping separate index/working-directory state.",
